-- Run only against the disposable local regression database; fixtures roll back.
begin;
set local statement_timeout='30s';
do $$declare owner_user uuid:=gen_random_uuid();member_user uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();viewer uuid:=gen_random_uuid();w uuid;other_w uuid;obj uuid;other_obj uuid;rec uuid;other_rec uuid;call_id uuid;private_call uuid;foreign_call uuid;template uuid;draft uuid;calendar uuid;integration uuid;result jsonb;n integer;begin
 insert into auth.users(id,email,aud,role,email_confirmed_at) select u,'meeting-test-'||u||'@example.invalid','authenticated','authenticated',now() from unnest(array[owner_user,member_user,outsider,viewer]) u;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);w:=public.create_workspace('Meeting local test');other_w:=public.create_workspace('Other meetings');
 select id into obj from public.objects where workspace_id=w and slug='companies';select id into other_obj from public.objects where workspace_id=other_w and slug='companies';
 insert into public.records(workspace_id,object_id,display_name) values(w,obj,'Client') returning id into rec;
 insert into public.records(workspace_id,object_id,display_name) values(other_w,other_obj,'Secret company') returning id into other_rec;
 insert into public.memberships(workspace_id,user_id,role) values(w,member_user,'member'),(w,viewer,'viewer');
 insert into public.meetings(workspace_id,record_id,title,starts_at,ends_at,transcript,participants) values(w,rec,'Public discovery','2026-10-10T10:00:00Z','2026-10-10T11:00:00Z','A public transcript','[{"name":"Alex","email":"alex@example.test"}]') returning id into call_id;
 insert into public.meetings(workspace_id,title,transcript,private) values(w,'Owner private call','SECRET-TRANSCRIPT',true) returning id into private_call;
 insert into public.meetings(workspace_id,record_id,title,transcript) values(other_w,other_rec,'Other tenant call','FOREIGN-TRANSCRIPT') returning id into foreign_call;
 insert into public.meeting_insight_templates(workspace_id,name,sections,status) values(w,'Published sales','[{"title":"Summary","prompt":"Summarize","format":"text"}]','published') returning id into template;
 insert into public.meeting_insight_templates(workspace_id,name,sections,status) values(w,'Owner private draft','[{"title":"Summary","prompt":"Summarize","format":"text"}]','draft') returning id into draft;
 insert into public.integrations(workspace_id,user_id,provider,email,status) values(w,owner_user,'google-calendar','owner@example.test','connected') returning id into integration;
 insert into public.communications(workspace_id,user_id,integration_id,provider_id,kind,subject,body,starts_at,recipients) values(w,owner_user,integration,'calendar-fixture','calendar','Owner appointment','PRIVATE-CALENDAR-BODY','2026-10-10T13:00:00Z',array['owner@example.test']) returning id into calendar;
 if has_function_privilege('anon','public.meeting_library(uuid,jsonb)','execute') or exists(select 1 from pg_proc where oid='public.meeting_library(uuid,jsonb)'::regprocedure and prosecdef) then raise exception 'Unsafe library grants';end if;
 execute 'set local role authenticated';
 result:=public.meeting_library(w);
 if (result->>'count')::int<>2 or result::text like '%SECRET-TRANSCRIPT%' or result::text like '%A public transcript%' or result::text like '%FOREIGN%' or result::text like '%"transcript":%' then raise exception 'Library leaked content or foreign source %',result;end if;
 result:=public.meeting_library(w,'{"view":"agenda"}');if (result->>'count')::int<>3 or result::text like '%PRIVATE-CALENDAR-BODY%' then raise exception 'Agenda leaked body';end if;
 result:=public.meeting_library(w,'{"q":"%"}');if (result->>'count')::int<>0 then raise exception 'Wildcard query interpreted as syntax';end if;
 insert into public.meeting_favorites(workspace_id,meeting_id) values(w,call_id);
 result:=public.meeting_library(w,'{"favorite":"only"}');if (result->>'count')::int<>1 or result->'data'->0->>'id'<>call_id::text then raise exception 'Personal favorite failed';end if;
 insert into public.meeting_record_links(workspace_id,meeting_id,record_id) values(w,private_call,rec);
 if (public.crm_record_context(w,rec,'timeline')->'counts'->>'meetings')::int<>2 then raise exception 'Linked meeting missing from record context';end if;
 begin insert into public.meeting_record_links(workspace_id,meeting_id,record_id) values(w,private_call,other_rec);raise exception 'Cross-tenant record linked';exception when foreign_key_violation or insufficient_privilege then null;end;
 update public.meetings set summary='Updated summary' where id=call_id;
 if (select version from public.meetings where id=call_id)<>2 then raise exception 'Meeting optimistic version failed';end if;
 begin update public.meetings set private=false where id=private_call;raise exception 'Private call widened';exception when insufficient_privilege then null;end;
 begin update public.meetings set ends_at=starts_at-interval '1 minute' where id=call_id;raise exception 'Invalid end order';exception when check_violation then null;end;
 begin update public.meetings set join_url='https://zoom.us.attacker.test/j/1' where id=call_id;raise exception 'Deceptive URL accepted';exception when check_violation then null;end;
 begin update public.meetings set participants='[{"name":"Alex","secret":"injected"}]' where id=call_id;raise exception 'Unknown participant properties accepted';exception when check_violation then null;end;
 begin update public.meeting_insight_templates set workspace_id=other_w where id=template;raise exception 'Template moved across tenants';exception when insufficient_privilege then null;end;
 begin update public.meeting_insight_templates set sections='[{"title":"A","prompt":"B","format":"script"}]' where id=template;raise exception 'Invalid template accepted';exception when check_violation then null;end;
 perform set_config('request.jwt.claim.sub',member_user::text,true);
 if (public.crm_record_context(w,rec,'timeline')->'counts'->>'meetings')::int<>1 then raise exception 'Record linking widened private meeting access';end if;
 begin insert into public.meetings(workspace_id,title,author_id) values(w,'Forged author',owner_user);raise exception 'Meeting author spoofed';exception when insufficient_privilege then null;end;
 result:=public.meeting_library(w);if (result->>'count')::int<>1 or result::text like '%Owner private call%' then raise exception 'Another member read private call';end if;
 result:=public.meeting_library(w,'{"view":"agenda"}');if (result->>'count')::int<>1 then raise exception 'Another member saw owner calendar';end if;
 if exists(select 1 from public.meeting_favorites) or exists(select 1 from public.meeting_record_links where meeting_id=private_call) or exists(select 1 from public.meeting_insight_templates where id=draft) then raise exception 'Private related state leaked';end if;
 if not exists(select 1 from public.meeting_insight_templates where id=template) then raise exception 'Published template not shared';end if;
 update public.meeting_insight_templates set name='Forged' where id=template;if found then raise exception 'Member modified someone else template';end if;
 begin insert into public.meeting_favorites(workspace_id,meeting_id,user_id) values(w,call_id,owner_user);raise exception 'Favorite author spoofed';exception when insufficient_privilege then null;end;
 begin insert into public.meeting_favorites(workspace_id,meeting_id) values(w,private_call);raise exception 'Private favorite inserted';exception when insufficient_privilege then null;end;
 begin insert into public.meeting_record_links(workspace_id,meeting_id,record_id) values(w,private_call,rec);raise exception 'Private meeting linked';exception when insufficient_privilege then null;end;
 begin insert into public.meeting_insight_templates(workspace_id,name,sections,created_by) values(w,'Forged','[{"title":"A","prompt":"B","format":"text"}]',owner_user);raise exception 'Template author spoofed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',viewer::text,true);if (public.meeting_library(w)->>'count')::int<>0 then raise exception 'Limited reader bypassed record scope';end if;
 begin insert into public.meeting_insight_templates(workspace_id,name,sections) values(w,'Viewer write','[{"title":"A","prompt":"B","format":"text"}]');raise exception 'Reader wrote template';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outsider::text,true);begin perform public.meeting_library(w);raise exception 'Outsider listed library';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.meeting_record_links) or exists(select 1 from public.meeting_insight_templates) then raise exception 'Cross-tenant related objects exposed';end if;
 perform set_config('request.jwt.claim.sub',owner_user::text,true);
 for n in 1..27 loop insert into public.meetings(workspace_id,title,transcript) values(w,'Paged call '||n,'text');end loop;
 result:=public.meeting_library(w,'{"q":"Paged call"}');if jsonb_array_length(result->'data')<>25 or (result->>'count')::int<>27 then raise exception 'Pagination not bounded';end if;
 result:=public.meeting_library(w,'{"q":"Paged call","page":1}');if jsonb_array_length(result->'data')<>2 then raise exception 'Second page missing';end if;
 begin perform public.meeting_library(w,'{"page":-1}');raise exception 'Negative page accepted';exception when invalid_parameter_value then null;end;
 perform set_config('request.jwt.claim.sub','',true);begin perform public.meeting_library(w);raise exception 'Missing auth accepted';exception when insufficient_privilege then null;end;
end $$;
rollback;
